import sys
from collections import defaultdict

def main():
    sys.setrecursionlimit(100000)
    input = sys.stdin.read().split()
    ptr = 0

    n = int(input[ptr])
    ptr += 1

    graph = defaultdict(list)

    for _ in range(n):
        v1 = input[ptr]
        v2 = input[ptr + 1]
        val = float(input[ptr + 2])
        ptr += 3
        graph[v1].append((v2, val))
        graph[v2].append((v1, 1.0 / val))

    q = int(input[ptr])
    ptr += 1

    queries = []
    for _ in range(q):
        v1 = input[ptr]
        v2 = input[ptr + 1]
        ptr += 2
        queries.append((v1, v2))

    def bfs(start, end):
        if start not in graph or end not in graph:
            return -1.0
        if start == end:
            return 1.0

        visited = {start}
        queue = [(start, 1.0)]

        while queue:
            curr, ratio = queue.pop(0)

            for neighbor, edge_val in graph[curr]:
                if neighbor == end:
                    return ratio * edge_val

                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, ratio * edge_val))

        return -1.0

    results = []
    for v1, v2 in queries:
        result = bfs(v1, v2)
        if result == -1.0:
            results.append("-1.0")
        else:
            results.append(str(result))

    print('\n'.join(results))

if __name__ == "__main__":
    main()
